 return <article className={`rp-card rp-menu-card ${m.available?'':'rp-sold'}`}><FoodArt art={m.art}/><div className="rp-menu-body"><div className="rp-row"><h3>{ur?m.name_ur:m.name}</h3><span className="rp-chip">{ur?catUr[m.category]??m.category:m.category}</span></div><p>{ur?(descUr[m.name]??m.description):m.description}</p><small>{say('Sample allergens:','نمونہ الرجی:')} {m.allergens.length?m.allergens.join(', '):say('none listed, confirm with staff','درج نہیں، عملے سے تصدیق کریں')}</small>{role==='restaurant'?<><label>{say('Sample price (PKR)','نمونہ قیمت (روپے)')}<input type="number" min="1" max="100000" value={price} onChange={e=>setPrice(e.target.value)}/></label><div className="rp-inline"><button className="rp-btn secondary small" disabled={pending||Number(price)===m.price} onClick={()=>void act('menu',{id:m.id,price:Number(price)}).catch(()=>{})}>{say('Save price','قیمت محفوظ')}</button><button className="rp-btn small" disabled={pending} onClick={()=>void act('menu',{id:m.id,available:!m.available}).catch(()=>{})}>{m.available?say('Mark sold out','ختم نشان لگائیں'):say('Make available','دستیاب کریں')}</button></div></>:<div className="rp-row"><span className="rp-price">{money(m.price)}</span><button className="rp-btn small" disabled={!m.available} onClick={()=>add(m)}>{m.available?say('+ Add','+ شامل'):say('Sold out','ختم')}</button></div>}</div></article>;
