function OrderRow(p:ViewProps&{o:Order;receipt:(o:Order)=>void}){const {o,say,s,ur}=p,next=nextOrderStatus(o);return <div className="rp-list-row"><div className="rp-row"><div><b>#{o.number} · {p.role==='customer'?label(o.mode,ur):guest(s,o.customer_id)}</b><p>{o.items.map(x=>`${x.quantity} × ${ur?x.name_ur:x.name}`).join(', ')}</p><small>{dateLabel(o.created_at,ur?'ur':'en')} · {timeLabel(o.created_at,ur?'ur':'en')} · {money(o.total)} · {o.source}</small><small style={{display:'block'}}>{say('Sample preparation estimate','نمونہ تیاری کا اندازہ')}: {timeLabel(o.estimated_at,ur?'ur':'en')} PKT</small></div><Status v={o.status} ur={ur}/></div><div className="rp-inline rp-gap"><button className="rp-btn secondary small" onClick={()=>p.receipt(o)}>{say('View receipt','رسید دیکھیں')}</button>{p.role==='restaurant'&&next&&<button className="rp-btn small" disabled={p.pending} onClick={()=>void p.act('order_status',{id:o.id,status:next}).catch(()=>{})}>{say('Mark','حالت')} {label(next,ur)}</button>}{(p.role==='customer'?o.status==='placed':['placed','accepted'].includes(o.status))&&<button className="rp-btn danger small" disabled={p.pending} onClick={()=>void p.act('order_status',{id:o.id,status:'cancelled'}).catch(()=>{})}>{say('Cancel order','آرڈر منسوخ')}</button>}{p.role==='restaurant'&&o.payment==='cash_due'&&o.status!=='cancelled'&&<button className="rp-btn secondary small" disabled={p.pending} onClick={()=>void p.act('payment',{id:o.id}).catch(()=>{})}>{say('Record demo payment','نمونہ ادائیگی درج')}</button>}<small>{o.payment==='paid_demo'?say('Paid, simulated','ادائیگی، ڈیمو'):say('Cash due, demo only','نقد واجب، صرف ڈیمو')}</small></div></div>}
function Orders(p:ViewProps&{receipt:(o:Order)=>void;reorder:(o:Order)=>void}){const [filter,setFilter]=useState('active'),[mode,setMode]=useState('all'),{s,say}=p;const orders=s.orders.filter(o=>(filter==='all'||filter==='active'&&!['completed','cancelled'].includes(o.status)||filter===o.status)&&(mode==='all'||o.mode===mode));return <><div className="rp-row"><div className="rp-tabs">{['active','all','completed','cancelled'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f==='active'?say('Active','جاری'):f==='all'?say('All orders','تمام آرڈر'):label(f,p.ur)}</button>)}</div><select style={{width:'auto'}} aria-label={say('Order mode filter','آرڈر فلٹر')} value={mode} onChange={e=>setMode(e.target.value)}>{['all','pickup','delivery','dine_in'].map(v=><option key={v} value={v}>{v==='all'?say('All modes','تمام طریقے'):label(v,p.ur)}</option>)}</select></div><div className="rp-card">{orders.map(o=><div key={o.id}><OrderRow {...p} o={o}/>{p.role==='customer'&&<button className="rp-btn secondary small rp-gap" onClick={()=>p.reorder(o)}>{say('Reorder with current menu prices','موجودہ نمونہ قیمت پر دوبارہ آرڈر')}</button>}</div>)}{!orders.length&&<Empty>{say('No orders in this view.','اس منظر میں کوئی آرڈر نہیں۔')}</Empty>}</div></>}
function Receipt({order:o,name,say,ur,onClose}:{order:Order;name:string;say:Say;ur:boolean;onClose:()=>void}){return <RModal title={say('Sample order receipt','نمونہ آرڈر رسید')} onClose={onClose}><div className="rp-receipt"><p className="rp-kicker">TABLEFLOW · NEXUSPOINT</p><h2>{name}</h2><p>{say('Fictional outreach receipt. No payment or tax invoice.','فرضی ڈیمو رسید۔ حقیقی ادائیگی یا ٹیکس رسید نہیں۔')}</p><div className="rp-row rp-gap"><b>#{o.number}</b><Status v={o.status} ur={ur}/></div><small>{dateLabel(o.created_at,ur?'ur':'en')} · {timeLabel(o.created_at,ur?'ur':'en')} PKT · {label(o.mode,ur)}</small><table><thead><tr><th>{say('Dish','کھانا')}</th><th>{say('Qty','مقدار')}</th><th>{say('Sample price','نمونہ قیمت')}</th></tr></thead><tbody>{o.items.map((x,i)=><tr key={i}><td>{ur?x.name_ur:x.name}<br/><small>{label(x.spice,ur)} · {x.notes}</small></td><td>{x.quantity}</td><td>{money(x.price*x.quantity)}</td></tr>)}</tbody></table><div className="rp-row"><b>{say('Total (menu only)','کل (صرف مینو)')}</b><b>{money(o.total)}</b></div><p className="rp-gap">{o.notes}</p><small>{o.payment==='paid_demo'?say('Payment recorded as a simulation.','ادائیگی صرف نمونہ ہے۔'):say('Cash due is a demo label. No money is collected.','نقد واجب صرف ڈیمو کی حالت ہے۔ رقم وصول نہیں ہوتی۔')}</small><h3 className="rp-gap">{say('Order history','آرڈر کی تاریخ')}</h3>{o.timeline.map((t,i)=><p key={i}>{label(t.status,ur)} · {timeLabel(t.at,ur?'ur':'en')} PKT</p>)}<div className="rp-modal-foot"><button className="rp-btn secondary" onClick={onClose}>{say('Close','بند کریں')}</button><button className="rp-btn" onClick={()=>window.print()}>{say('Print / save PDF','پرنٹ / PDF محفوظ')}</button></div></div></RModal>}
function Reserve(p:ViewProps&{existing:Reservation|null;onClose:()=>void;onDone:()=>void}){const {s,say,existing}=p,[date,setDate]=useState(existing?localDate(existing.starts_at):localDate(s.server_time)),[party,setParty]=useState(existing?.party??4),[start,setStart]=useState(''),[notes,setNotes]=useState(''),[customer,setCustomer]=useState(s.customer.id),[error,setError]=useState('');const retry=useRef(crypto.randomUUID());const slots=tableSlots(date,party,s.tables,s.busy,s.settings,s.expires_at,new Date(s.server_time));const submit=async()=>{setError('');try{await p.act(existing?'reservation':'reserve',existing?{id:existing.id,start}:{party,start,notes,requestId:retry.current,...(p.role==='restaurant'?{customerId:customer}:{})});p.onDone();}catch(e){setError(e instanceof Error?e.message:'Connection problem');}};return <RModal title={existing?say('Reschedule your sample table','نمونہ میز کا وقت بدلیں'):say('Reserve a sample table','نمونہ میز بک کریں')} onClose={p.onClose}><p>{say('Fictional tables and availability. Reservations last 90 minutes. All times PKT.','میزیں اور دستیابی فرضی ہیں۔ بکنگ ۹۰ منٹ کے لیے ہے۔ تمام اوقات پاکستان کے ہیں۔')}</p>{error&&<div className="rp-error" role="alert">{error}</div>}<div className="rp-fields">{p.role==='restaurant'&&!existing&&<label className="full">{say('Sample guest','نمونہ مہمان')}<select value={customer} onChange={e=>setCustomer(e.target.value)}>{s.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}<label>{say('Visit date','تاریخ')}<input type="date" min={localDate(s.server_time)} max={dayAfter(localDate(s.server_time),13)} value={date} onChange={e=>{setDate(e.target.value);setStart('');}}/></label><label>{say('Party size','مہمانوں کی تعداد')}<select value={party} disabled={!!existing} onChange={e=>{setParty(Number(e.target.value));setStart('');}}>{Array.from({length:8},(_,i)=>i+1).map(n=><option key={n} value={n}>{n} {say('guests','مہمان')}</option>)}</select></label></div><h3>{say('Available sample times','نمونہ دستیاب اوقات')}</h3><div className="rp-slot-grid">{slots.map(t=><button className={t===start?'active':''} key={t} onClick={()=>setStart(t)}>{timeLabel(t,p.ur?'ur':'en')}</button>)}</div>{!slots.length&&<Empty>{say('No available table times. Try another day or a smaller party.','کوئی وقت دستیاب نہیں۔ دوسرا دن یا کم مہمان منتخب کریں۔')}</Empty>}<label>{say('Fictional booking notes','نمونہ بکنگ کی ہدایات')}<textarea maxLength={500} value={notes} onChange={e=>setNotes(e.target.value)}/></label><div className="rp-modal-foot"><button className="rp-btn secondary" onClick={p.onClose}>{say('Close','بند کریں')}</button><button className="rp-btn" disabled={!start||!slots.includes(start)||p.pending} onClick={submit}>{p.pending?say('Saving…','محفوظ ہو رہا ہے…'):say('Confirm sample table','نمونہ میز کی تصدیق')}</button></div></RModal>}
function Reservations(p:ViewProps&{edit:(r:Reservation)=>void}){const {s,say,ur}=p,[date,setDate]=useState(''),[status,setStatus]=useState('active'),filtered=s.reservations.filter(r=>(!date||localDate(r.starts_at)===date)&&(status==='all'||['confirmed','seated'].includes(r.status)));return <><div className="rp-row"><div className="rp-tabs">{['active','all'].map(v=><button key={v} className={status===v?'active':''} onClick={()=>setStatus(v)}>{v==='active'?say('Upcoming & seated','آئندہ اور میز پر'):say('All bookings','تمام بکنگ')}</button>)}</div><label style={{maxWidth:190}}>{say('Filter day','دن کا فلٹر')}<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label></div><div className="rp-card rp-gap">{filtered.map(r=><div key={r.id} className="rp-list-row"><div className="rp-row"><div><b>{dateLabel(r.starts_at,ur?'ur':'en')} · {timeLabel(r.starts_at,ur?'ur':'en')} PKT</b><p>{s.tables.find(t=>t.id===r.table_id)?.name} · {r.party} {say('guests','مہمان')} · {p.role==='restaurant'?guest(s,r.customer_id):say('90-minute reservation','۹۰ منٹ کی بکنگ')}</p><small>{r.notes} · {r.source}</small></div><Status v={r.status} ur={ur}/></div><div className="rp-inline rp-gap">{r.status==='confirmed'&&<><button className="rp-btn secondary small" onClick={()=>p.edit(r)}>{say('Reschedule','وقت بدلیں')}</button><button className="rp-btn danger small" disabled={p.pending} onClick={()=>void p.act('reservation',{id:r.id,status:'cancelled'}).catch(()=>{})}>{say('Cancel','منسوخ')}</button>{p.role==='restaurant'&&<><button className="rp-btn small" disabled={p.pending||localDate(r.starts_at)!==localDate(s.server_time)} onClick={()=>void p.act('reservation',{id:r.id,status:'seated'}).catch(()=>{})}>{say('Seat guests','مہمان بٹھائیں')}</button><button className="rp-btn secondary small" disabled={p.pending} onClick={()=>void p.act('reservation',{id:r.id,status:'no_show'}).catch(()=>{})}>{say('No-show','نہیں آئے')}</button></>}</>}{r.status==='seated'&&p.role==='restaurant'&&<button className="rp-btn small" disabled={p.pending} onClick={()=>void p.act('reservation',{id:r.id,status:'completed'}).catch(()=>{})}>{say('Finish table','میز مکمل')}</button>}</div></div>)}{!filtered.length&&<Empty>{say('No table bookings in this view.','اس منظر میں کوئی میز بکنگ نہیں۔')}</Empty>}</div></>}
function Tables(p:ViewProps&{reserve:()=>void}){const {s,say,ur}=p,[wait,setWait]=useState(false),[customer,setCustomer]=useState(s.customer.id),[party,setParty]=useState(4);return <><div className="rp-grid">{s.tables.map(t=>{const seated=s.reservations.find(r=>r.table_id===t.id&&r.status==='seated'),upcoming=s.reservations.find(r=>r.table_id===t.id&&r.status==='confirmed'&&new Date(r.ends_at)>new Date(s.server_time));return <div key={t.id} className={`rp-card rp-table-card ${seated?'occupied':''}`}><div className="rp-row"><h2>{t.name}</h2><span className="rp-status">{!t.active?say('Blocked','بند'):seated?say('Occupied','مصروف'):say('Open','کھلی')}</span></div><div className="rp-table-scene"><RIcon name="table"/></div><div className="rp-row"><b>{t.seats} {say('seats','نشستیں')}</b><small>{t.area}</small></div><small>{seated?`${guest(s,seated.customer_id)} · ${seated.party} ${say('guests','مہمان')}`:upcoming?`${say('Next booking','اگلی بکنگ')}: ${dateLabel(upcoming.starts_at,ur?'ur':'en')} ${timeLabel(upcoming.starts_at,ur?'ur':'en')}`:say('No upcoming booking','کوئی آئندہ بکنگ نہیں')}</small><button className="rp-btn secondary small" disabled={p.pending} onClick={()=>void p.act('table',{id:t.id,active:!t.active}).catch(()=>{})}>{t.active?say('Block table','میز بند کریں'):say('Reopen table','میز کھولیں')}</button>{seated&&<button className="rp-btn small" disabled={p.pending} onClick={()=>void p.act('reservation',{id:seated.id,status:'completed'}).catch(()=>{})}>{say('Finish & release table','مکمل اور میز خالی')}</button>}</div>;})}</div><div className="rp-card rp-gap"><div className="rp-card-head"><h2>{say('Walk-in waitlist','آنے والے مہمانوں کا انتظار')}</h2><button className="rp-btn secondary small" onClick={()=>setWait(true)}>{say('+ Add waiting party','+ انتظار شامل')}</button></div>{s.waitlist.filter(w=>['waiting','notified'].includes(w.status)).map(w=><div className="rp-list-row rp-row" key={w.id}><div><b>{guest(s,w.customer_id)} · {w.party} {say('guests','مہمان')}</b><p>{timeLabel(w.created_at,ur?'ur':'en')} PKT · {label(w.status,ur)}</p></div><div className="rp-inline"><button className="rp-btn secondary small" disabled={p.pending} onClick={()=>void p.act('waitlist',{id:w.id,status:'notified'}).catch(()=>{})}>{say('Simulate notification','نمونہ اطلاع')}</button><button className="rp-btn secondary small" disabled={p.pending} onClick={()=>void p.act('waitlist',{id:w.id,status:'cancelled'}).catch(()=>{})}>{say('Remove','ہٹائیں')}</button><button className="rp-btn small" onClick={p.reserve}>{say('Book a table','میز بک کریں')}</button></div></div>)}{!s.waitlist.some(w=>['waiting','notified'].includes(w.status))&&<Empty>{say('No waiting parties.','کوئی مہمان انتظار میں نہیں۔')}</Empty>}<small>{say('Notifications are simulated. After allocating a reservation, remove the waiting party.','اطلاعات صرف نمونہ ہیں۔ میز بک کرنے کے بعد انتظار سے ہٹائیں۔')}</small></div>{wait&&<RModal title={say('Add sample waiting guests','نمونہ انتظار شامل کریں')} onClose={()=>setWait(false)}><div className="rp-fields"><label>{say('Sample guest','نمونہ مہمان')}<select value={customer} onChange={e=>setCustomer(e.target.value)}>{s.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>{say('Party size','مہمانوں کی تعداد')}<input type="number" min={1} max={20} value={party} onChange={e=>setParty(Number(e.target.value))}/></label></div><button className="rp-btn" disabled={p.pending} onClick={()=>void p.act('waitlist',{party,customerId:customer}).then(()=>setWait(false)).catch(()=>{})}>{say('Add to waitlist','انتظار میں شامل')}</button></RModal>}</>}
function Kitchen(p:ViewProps&{completed:boolean}){const {s,say,ur}=p;const groups=p.completed?['completed','cancelled']:['accepted','preparing','ready'];return <><div className="rp-grid four"><Stat n={s.orders.filter(o=>o.status==='accepted').length} title={say('To prepare','تیاری باقی')} icon="order"/><Stat n={s.orders.filter(o=>o.status==='preparing').length} title={say('Cooking now','تیاری جاری')} icon="chef"/><Stat n={s.orders.filter(o=>o.status==='ready').length} title={say('Ready to serve','پیش کرنے کو تیار')} icon="check"/><Stat n={s.settings.prep_minutes+' min'} title={say('Sample prep estimate','نمونہ تیاری کا اندازہ')} icon="clock"/></div><p className="rp-note">{say('Manager acceptance sends new orders here. Timers show elapsed ticket time. Read every preference before preparing.','منیجر کی منظوری کے بعد آرڈر یہاں آتے ہیں۔ ٹائمر ٹکٹ کا گزرا وقت دکھاتا ہے۔ تمام ہدایات پڑھیں۔')}</p><div className="rp-board rp-gap">{groups.map(g=><section className="rp-board-col" key={g}><div className="rp-row"><h2>{label(g,ur)}</h2><span className="rp-chip">{s.orders.filter(o=>o.status===g).length}</span></div>{s.orders.filter(o=>o.status===g).map(o=><article className={`rp-card rp-ticket ${o.status}`} key={o.id}><div className="rp-row"><h2>#{o.number}</h2><span className="rp-time">{Math.max(0,Math.floor((new Date(s.server_time).getTime()-new Date(o.created_at).getTime())/60000))} {say('min','منٹ')}</span></div><small>{label(o.mode,ur)} · {o.table_id?s.tables.find(t=>t.id===o.table_id)?.name:say('Sample ticket','نمونہ ٹکٹ')}</small><div className="rp-ticket-items">{o.items.map((x,i)=><div key={i}><strong>{x.quantity}×</strong><p>{ur?x.name_ur:x.name}<small>{label(x.spice,ur)} · {x.notes||say('No extra notes','اضافی ہدایات نہیں')}</small></p></div>)}</div>{o.notes&&<p className="rp-note">{o.notes}</p>}{['accepted','preparing'].includes(o.status)&&<button className="rp-btn rp-gap" disabled={p.pending} onClick={()=>void p.act('order_status',{id:o.id,status:o.status==='accepted'?'preparing':'ready'}).catch(()=>{})}>{o.status==='accepted'?say('Start preparing','تیاری شروع'):say('Mark ready','تیار نشان لگائیں')}</button>}{o.status==='ready'&&<small>{say('Waiting for front-of-house handoff','عملے کے حوالے کرنے کا انتظار')}</small>}</article>)}{!s.orders.some(o=>o.status===g)&&<Empty>{say('No tickets here','کوئی ٹکٹ نہیں')}</Empty>}</section>)}</div></>}
function Inbox(p:ViewProps){const {s,say,ur}=p,[selected,setSelected]=useState(''),[text,setText]=useState(''),[assignment,setAssignment]=useState('Front desk');const c=s.conversations.find(c=>c.id===selected)??s.conversations[0],customer=s.customers.find(x=>x.visitor===c?.visitor);if(!c)return <div className="rp-card"><Empty>{say('Customer conversations appear here after the first message.','پہلے پیغام کے بعد گفتگو یہاں نظر آئے گی۔')}</Empty></div>;return <div className="rp-inbox"><div className="rp-card rp-inbox-list">{s.conversations.map(x=><button key={x.id} className={x.id===c.id?'active':''} onClick={()=>setSelected(x.id)}><b>{s.customers.find(g=>g.visitor===x.visitor)?.name??say('Demo guest','نمونہ مہمان')}</b><small>{x.summary??x.messages.at(-1)?.content}</small><Status ur={ur} v={x.staff_mode?'waiting':'ready'}/></button>)}</div><div className="rp-card"><div className="rp-row"><h2>{customer?.name??say('Conversation','گفتگو')}</h2><button className="rp-btn small" disabled={p.pending} onClick={()=>void p.act('conversation',{id:c.id,staffMode:!c.staff_mode,assignedTo:assignment}).catch(()=>{})}>{c.staff_mode?say('Return to assistant','اسسٹنٹ کو واپس'):say('Take over','گفتگو سنبھالیں')}</button></div><small>{c.staff_mode?say('Staff is replying. Assistant paused.','عملہ جواب دے رہا ہے۔ اسسٹنٹ بند ہے۔'):say('Assistant is replying','اسسٹنٹ جواب دے رہا ہے')} · {c.assigned_to??say('Unassigned','غیر مقرر')}</small><div className="rp-transcript">{c.messages.map((m,i)=><div className={`rp-bubble ${m.role}`} key={i}><p dir="auto">{m.content}</p><small>{m.role==='customer'?say('Guest','مہمان'):m.source==='staff'?say('Staff','عملہ'):say('Assistant','اسسٹنٹ')} · {timeLabel(m.at,ur?'ur':'en')}</small></div>)}</div><form onSubmit={e=>{e.preventDefault();void p.act('conversation',{id:c.id,text}).then(()=>setText('')).catch(()=>{});}} className="rp-inline"><input value={text} onChange={e=>setText(e.target.value)} maxLength={2000} disabled={!c.staff_mode} aria-label={say('Staff reply','عملے کا جواب')} placeholder={c.staff_mode?say('Reply as staff…','عملے کا جواب…'):say('Take over to reply','جواب کے لیے گفتگو سنبھالیں')}/><button className="rp-btn" disabled={!c.staff_mode||!text.trim()||p.pending}>{say('Send','بھیجیں')}</button></form></div><div className="rp-card rp-inbox-context rp-stack"><h2>{say('Guest context','مہمان کی تفصیلات')}</h2><label>{say('Assign staff','عملہ مقرر کریں')}<input value={assignment} maxLength={80} onChange={e=>setAssignment(e.target.value)}/></label><button className="rp-btn secondary small" disabled={p.pending} onClick={()=>void p.act('conversation',{id:c.id,assignedTo:assignment}).catch(()=>{})}>{say('Save assignment','عملہ محفوظ')}</button><h3>{say('Recent orders','تازہ آرڈر')}</h3>{s.orders.filter(o=>o.customer_id===customer?.id).slice(0,3).map(o=><div key={o.id}><b>#{o.number} · {money(o.total)}</b><small style={{display:'block'}}>{label(o.status,ur)} · {label(o.mode,ur)}</small></div>)}<h3>{say('Table bookings','میز بکنگ')}</h3>{s.reservations.filter(r=>r.customer_id===customer?.id&&r.status==='confirmed').map(r=><small key={r.id}>{r.party} {say('guests','مہمان')} · {dateLabel(r.starts_at,ur?'ur':'en')} {timeLabel(r.starts_at,ur?'ur':'en')}</small>)}</div></div>}
function Guests(p:ViewProps){const {s,say,ur}=p,[query,setQuery]=useState('');return <><div className="rp-search"><RIcon name="search"/><input value={query} onChange={e=>setQuery(e.target.value)} aria-label={say('Search guests','مہمان تلاش')} placeholder={say('Search sample guests','نمونہ مہمان تلاش کریں')}/></div><div className="rp-grid">{s.customers.filter(c=>c.name.toLowerCase().includes(query.toLowerCase())).map(c=><div key={c.id} className="rp-card rp-stack"><div className="rp-inline"><span className="rp-avatar">{c.name.slice(0,2)}</span><h2>{c.name}</h2></div><small>{say('Fictional demo guest','فرضی مہمان')}</small><div className="rp-row"><span>{say('Orders','آرڈر')}</span><b>{s.orders.filter(o=>o.customer_id===c.id).length}</b></div><div className="rp-row"><span>{say('Table bookings','میز بکنگ')}</span><b>{s.reservations.filter(r=>r.customer_id===c.id).length}</b></div><small>{s.orders.find(o=>o.customer_id===c.id)?`${say('Latest','تازہ')}: ${dateLabel(s.orders.find(o=>o.customer_id===c.id)!.created_at,ur?'ur':'en')}`:say('No orders yet','ابھی آرڈر نہیں')}</small></div>)}</div></>}
function Settings(p:ViewProps){const {s,say}=p,[prep,setPrep]=useState(s.settings.prep_minutes),[open,setOpen]=useState(s.settings.open_min),[close,setClose]=useState(s.settings.close_min);const clock=(n:number)=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;return <div className="rp-grid two"><div className="rp-card rp-stack"><h2>{say('Order intake','آرڈر وصولی')}</h2><p>{say('Pause new sample orders during a busy service. Existing kitchen tickets stay active.','رش میں نئے نمونہ آرڈر بند کریں۔ پہلے سے موجود ٹکٹ جاری رہتے ہیں۔')}</p><button className="rp-btn" disabled={p.pending} onClick={()=>void p.act('settings',{accepting:!s.settings.accepting}).catch(()=>{})}>{s.settings.accepting?say('Pause ordering','آرڈر بند کریں'):say('Resume ordering','آرڈر کھولیں')}</button><label>{say('Sample preparation estimate (minutes)','نمونہ تیاری کا اندازہ (منٹ)')}<input type="number" min={10} max={120} value={prep} onChange={e=>setPrep(Number(e.target.value))}/></label><button className="rp-btn secondary" disabled={p.pending} onClick={()=>void p.act('settings',{prepMinutes:prep}).catch(()=>{})}>{say('Save estimate','اندازہ محفوظ')}</button></div><div className="rp-card rp-stack"><h2>{say('Table booking hours','میز بکنگ کے اوقات')}</h2><p>{say('Illustrative daily hours. Changing hours cannot invalidate an existing reservation. Move conflicting bookings first.','روزانہ نمونہ اوقات۔ موجود بکنگ سے ٹکراؤ ہو تو پہلے بکنگ کا وقت بدلیں۔')}</p><label>{say('Opens (PKT)','کھلنے کا وقت')}<select value={open} onChange={e=>setOpen(Number(e.target.value))}>{Array.from({length:46},(_,i)=>i*30).map(n=><option key={n} value={n}>{clock(n)}</option>)}</select></label><label>{say('Closes (PKT)','بند ہونے کا وقت')}<select value={close} onChange={e=>setClose(Number(e.target.value))}>{Array.from({length:46},(_,i)=>(i+3)*30).map(n=><option key={n} value={n}>{clock(n)}</option>)}</select></label><button className="rp-btn secondary" disabled={p.pending} onClick={()=>void p.act('settings',{openMin:open,closeMin:close}).catch(()=>{})}>{say('Save sample hours','نمونہ اوقات محفوظ')}</button><small>{say('90-minute bookings · 30-minute start times · Next 14 days','۹۰ منٹ بکنگ · ۳۰ منٹ کے وقفے · اگلے ۱۴ دن')}</small></div></div>}

function AddGuest(p:ViewProps){const [name,setName]=useState('');return <form className="rp-card rp-inline" style={{marginBottom:20}} onSubmit={e=>{e.preventDefault();void p.act('guest',{name}).then(()=>setName('')).catch(()=>{});}}><label style={{flex:1}}>{p.say('New fictional guest','نیا فرضی مہمان')}<input value={name} onChange={e=>setName(e.target.value)} maxLength={80} placeholder={p.say('Sample guest name','نمونہ مہمان کا نام')}/></label><button className="rp-btn" disabled={!name.trim()||p.pending}>{p.say('Add guest','مہمان شامل')}</button></form>;}
